ection\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"}},\"elements\":[{\"id\":\"9229165\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"a18993b\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/Senateur\\/wp-content\\/uploads\\/2026\\/09\\/pexels-photo-36607738-36607738.jpg\",\"id\":1664,\"size\":\"\",\"alt\":\"A vibrant aerial view of Mount Aureol and its colorful houses in Freetown, Sierra Leone.\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"47d5544\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\"},\"elements\":[{\"id\":\"d03477e\",\"elType\":\"widget\",\"settings\":{\"title\":\"Danyi en Chiffres\",\"header_size\":\"h4\",\"typography_typography\":\"custom\",\"typography_text_decoration\":\"underline\",\"title_color\":\"#38AB03\",\"title_hover_color\":\"#6FFC13\",\"title_hover_color_transition_duration\":{\"unit\":\"s\",\"size\":0.6,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":true},{\"id\":\"6fb9eae\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Altitude Moyenne\\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 700 m<br \\/>Population active\\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a045 000<br \\/>Sp\\u00e9cialit\\u00e9s\\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0Caf\\u00e9, Cacao<\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"fba8c49\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elemen