(9, 1, '2026-09-21 17:10:10', '2026-09-21 15:10:10', '/* Fond blanc pour l\'en-tête sur toutes les pages sauf Accueil */\nbody:not(.home) .main-header-bar {\n  background-color: #ffffff !important;\n}\n\n/* Menu + Slogan en BLEU FONCÉ sur fond blanc */\nbody:not(.home) .main-header-menu a,\nbody:not(.home) .elementor-nav-menu a,\nbody:not(.home) .site-description,\nbody:not(.home) .ast-site-title-wrap,\nbody:not(.home) .site-header p {\n  color: #0A3D62 !important;\n}\n\n/* Menu + Slogan en BLANC sur l\'Accueil */\nbody.home .main-header-menu a,\nbody.home .elementor-nav-menu a,\nbody.home .site-description,\nbody.home .ast-site-title-wrap {\n  color: #ffffff !important;\n}\n\n/* 1. Réduire la hauteur de la barre blanche sur les pages autres que Accueil */\nbody:not(.home) .main-header-bar {\n  padding-top: 6px !important;\n  padding-bottom: 2px !important;\n}\n\n/* 2. Faire descendre un peu les icônes réseaux sociaux */\n.ast-above-header-bar .ast-social-icons,\n.site-header .ast-header-social-wrap {\n  margin-top: 6px !important;\n}\n\n/* Couleur de la page active dans le menu */\n.main-header-menu .current-menu-item > a,\n.main-header-menu .current_page_item > a,\n.elementor-nav-menu .current-menu-item > a {\n  color: #CE1126 !important; /* Rouge du drapeau Togo */\n  font-weight: 700 !important;\n  border-bottom: 2px solid #CE1126;\n}\n\n/* Logo officiel RT attrayant */\n.site-logo img {\n  width: 68px !important;\n  height: auto !important;\n  background: white;\n  border-radius: 50%;\n  padding: 3px;\n  border: 2px solid #FFCE00;\n  box-shadow: 0 0 10px rgba(0,0,0,0.3);\n}\n\n/* Forcer le même logo partout */\n.ast-theme-transparent-header .transparent-custom-logo {\n  display: none !important;\n}\n.ast-theme-transparent-header .custom-logo {\n  display: block !important;\n}', 'astra', '', 'publish', 'closed', 'closed', '', 'astra', '', '', '2026-09-25 13:21:15', '2026-09-25 11:21:15', '', 0, 'http://localhost/Senateur/?p=9', 0, 'custom_css', '', 0),
